      <g id="bop" data-s><rect x="283" y="96" width="34" height="22" rx="2" class="bop"/><line x1="283" y1="103" x2="317" y2="103" class="bopl"/><line x1="283" y1="111" x2="317" y2="111" class="bopl"/></g>
